async function getCommute(address) {
  const origin = encodeURIComponent(address);
  const dest = encodeURIComponent("Massachusetts Institute of Technology, 77 Massachusetts Ave, Cambridge, MA 02139");
  const url = `https://www.google.com/maps/dir/${origin}/${dest}/`;
  await tool.navigate({ tabId: workerTabId, url });
  await tool.wait_for({ tabId: workerTabId, condition: "dom_settled", timeout_ms: 6000 });

  const res = await browserjs(workerTabId, () => {
    const text = document.body.innerText;
    const matches = Array.from(text.matchAll(/(\d+\s*hr\s*)?(\d+)\s*min/gi)).map(m => m[0]);
    return {
      times: matches.slice(0, 10),
      rawTextSample: text.split('\n').filter(l => l.includes('min')).slice(0, 6)
    };
  });
  return res;
}

