    // Look for rent / beds in pricing sections
    const models = Array.from(document.querySelectorAll(".pricingGridItem, .rentalGridRow, [data-tab-content-id='all'] .tab-slice, .unitContainer, .priceBedRangeInfo")).map(el => el.textContent?.trim().replace(/\s+/g, ' '));

    return { title, address, models: models.slice(0, 10), fullTextSample: fullText.slice(0, 1200) };
  });

  console.log(`Page details for ${cand.title}:`, {
    title: pageDetails.title,
    address: pageDetails.address,
    modelsSample: pageDetails.models.slice(0, 3)
  });

  // Let's inspect the models or text for 1-bed <= 3000 or 2-bed <= 5000
