  const el = elements[0];
  let cur = el;
  const path = [];
  while (cur && cur !== document.body) {
    path.push({
      tag: cur.tagName,
      className: cur.className,
      id: cur.id,
      href: cur.getAttribute("href"),
      dataTestid: cur.getAttribute("data-testid")
    });
    cur = cur.parentElement;
  }
  return path;
});
