const tabId = 787784340;

const urlsToFetch = [
  "https://www.rent.com/massachusetts/cambridge-apartments/1-bedroom-under-3000",
  "https://www.rent.com/massachusetts/cambridge-apartments/1-bedroom-under-3000/page-2",
  "https://www.rent.com/massachusetts/cambridge-apartments/2-bedroom-under-5000",
  "https://www.rent.com/massachusetts/cambridge-apartments/2-bedroom-under-5000/page-2",
  "https://www.rent.com/massachusetts/boston-apartments/back-bay-neighborhood/1-bedroom-under-3000",
  "https://www.rent.com/massachusetts/somerville-apartments/1-bedroom-under-3000"
];

const allCandidates = [];
const seenUrls = new Set();

for (const url of urlsToFetch) {
  console.log(`Navigating to ${url}...`);
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  const pageCandidates = await browserjs(tabId, () => {
    const items = Array.from(document.querySelectorAll("li[id^='srp-scroll-target']"));
    return items.map(li => {
      const script = li.querySelector("script[type='application/ld+json']");
      let json = null;
      try { json = JSON.parse(script.textContent); } catch(e){}
      const link = li.querySelector("a[href*='/apartment/']")?.href || json?.url;
      const text = li.innerText.replace(/\s+/g, ' ').trim();
      return {
        name: json?.name || li.querySelector("h2, h3")?.textContent?.trim(),
        address: json?.address?.streetAddress ? `${json.address.streetAddress}, ${json.address.addressLocality}, ${json.address.addressRegion} ${json.address.postalCode}` : null,
        url: link,
        textSnippet: text.slice(0, 200)
      };
    }).filter(x => x.url);
  });

  console.log(`Extracted ${pageCandidates.length} from ${url}`);
  for (const c of pageCandidates) {
    if (c.url && !seenUrls.has(c.url)) {
      seenUrls.add(c.url);
      allCandidates.push(c);
    }
  }
}

console.log(`Total unique Rent.com candidates: ${allCandidates.length}`);
await write("tmp://rent_candidates.json", JSON.stringify(allCandidates, null, 2));

