const cands = JSON.parse((await read("tmp://rent_candidates.json")).text);
let verified = JSON.parse((await read("tmp://verified_listings.json")).text);
const workerTabId = 787784308;

console.log(`Starting with ${verified.length} verified listings.`);

// Function to check commute
async function checkCommute(address) {
  const origin = encodeURIComponent(address);
  const dest = encodeURIComponent("Massachusetts Institute of Technology, 77 Massachusetts Ave, Cambridge, MA 02139");
  const url = `https://www.google.com/maps/dir/${origin}/${dest}/`;
  await tool.navigate({ tabId: workerTabId, url });
  await tool.wait_for({ tabId: workerTabId, condition: "dom_settled", timeout_ms: 6000 });

  const res = await browserjs(workerTabId, () => {
    const text = document.body.innerText;
    const matches = Array.from(text.matchAll(/(\d+\s*hr\s*)?(\d+)\s*min/gi)).map(m => m[0]);
    return matches.slice(0, 6);
  });
  return res;
}

// Let's inspect candidates starting from index 2
for (let i = 2; i < cands.length && verified.length < 10; i++) {
  const cand = cands[i];
  console.log(`\n[${i}] Checking: ${cand.name} (${cand.url})`);

  // Create tab
  const newTab = await tool.tabs_create({ url: cand.url });
  const tabId = newTab.details.tabId;

  // Short pause to let navigation start
  await new Promise(r => setTimeout(r, 1000));
  try {
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  } catch(e) {
    console.log("Wait for load failed or already loaded:", e.message);
  }

  // Extract info
  const info = await browserjs(tabId, () => {
    const h1 = document.querySelector("h1")?.textContent?.trim();
    const addr = document.querySelector("[data-tid='property-address'], address, .property-address")?.textContent?.trim() || "";
    const text = document.body.innerText;
    return {
      h1,
      addr,
      textSnippet: text.slice(0, 1500)
    };
  });

  console.log("Listing text snippet:", info.textSnippet.slice(0, 250).replace(/\n/g, ' '));

  // Let's parse rent and beds
  // Check if there is 1 Bed or 2 Bed within budget
  // Patterns like "$2,895" or "$3,400"
  const priceMatches = Array.from(info.textSnippet.matchAll(/\$([0-9,]+)/g)).map(m => parseInt(m[1].replace(/,/g, ''), 10));

  // Look specifically around "1 Bed" or "2 Bed"
  let matchFound = null;

  // Check 1 bed under 3000
  const oneBedMatch = info.textSnippet.match(/(\$[0-9,]+)[\s\S]{1,60}1\s*Bed/i) || info.textSnippet.match(/1\s*Bed[\s\S]{1,60}(\$[0-9,]+)/i);
  // Check 2 bed under 5000
  const twoBedMatch = info.textSnippet.match(/(\$[0-9,]+)[\s\S]{1,60}2\s*Bed/i) || info.textSnippet.match(/2\s*Bed[\s\S]{1,60}(\$[0-9,]+)/i);

  if (oneBedMatch) {
    const priceVal = parseInt(oneBedMatch[1].replace(/[^0-9]/g, ''), 10);
    if (priceVal <= 3000 && priceVal >= 1000) {
      matchFound = { beds: "1 Bed", rent: `$${priceVal.toLocaleString()}` };
    }
  }

  if (!matchFound && twoBedMatch) {
    const priceVal = parseInt(twoBedMatch[1].replace(/[^0-9]/g, ''), 10);
    if (priceVal <= 5000 && priceVal >= 1500) {
      matchFound = { beds: "2 Bed", rent: `$${priceVal.toLocaleString()}` };
    }
  }

  // Fallback: check general price and bed indicators in snippet
  if (!matchFound) {
    const has1Bed = /1\s*Bed/i.test(info.textSnippet);
    const has2Bed = /2\s*Bed/i.test(info.textSnippet);
    const minPrice = priceMatches.filter(p => p >= 1200 && p <= 6000).sort((a,b) => a-b)[0];

    if (has1Bed && minPrice && minPrice <= 3000) {
      matchFound = { beds: "1 Bed", rent: `$${minPrice.toLocaleString()}` };
    } else if (has2Bed && minPrice && minPrice <= 5000) {
      matchFound = { beds: "2 Bed", rent: `$${minPrice.toLocaleString()}` };
    }
  }

  if (!matchFound) {
    console.log("No matching 1-bed <= 3000 or 2-bed <= 5000 found. Closing tab.");
    await tool.tabs_close({ tabId });
    continue;
  }

  console.log(`Matched criteria: ${matchFound.beds}, ${matchFound.rent}`);

  // Check commute
  const addressToCheck = cand.address || info.addr || info.h1 + ", Cambridge, MA";
  const commuteTimes = await checkCommute(addressToCheck);
  console.log(`Commute times for ${addressToCheck}:`, commuteTimes);

  // Check if any commute time is <= 20 min
  const minutes = commuteTimes.map(t => {
    const m = t.match(/(\d+)\s*min/);
    return m ? parseInt(m[1], 10) : 999;
  });

  const bestTime = Math.min(...minutes);
  if (bestTime <= 20) {
    console.log(`Commute OK (${bestTime} min). KEEPING TAB ${tabId} OPEN!`);
    const record = {
      tabId,
      building: info.h1 || cand.name,
      address: cand.address || info.addr,
      rent: matchFound.rent,
      beds: matchFound.beds,
      commute: `${bestTime} min to MIT`,
      link: cand.url
    };
    verified.push(record);
    await write("tmp://verified_listings.json", JSON.stringify(verified, null, 2));
  } else {
    console.log(`Commute too long (${bestTime} min > 20 min). Closing tab.`);
    await tool.tabs_close({ tabId });
  }
}

console.log(`Total verified listings after batch: ${verified.length}`);

