let verified = JSON.parse((await read("tmp://verified_listings.json")).text);

// Function to get clean floor plan details from a rent.com tab
async function getCleanFloorPlans(tabId) {
  return await browserjs(tabId, () => {
    // Look for floor plan items / table / text
    const plans = Array.from(document.querySelectorAll("[data-tid='floorplan-card'], .floorplan-item, [id*='floorplan'], tr")).map(el => el.innerText.replace(/\s+/g, ' ').trim());
    const fullText = document.body.innerText;

    // Look for all 1 Bed and 2 Bed price lines
    const lines = fullText.split('\n').map(l => l.trim()).filter(Boolean);
    const bedLines = [];
    for (let i = 0; i < lines.length; i++) {
      if (/1\s*Bed|2\s*Bed|Studio/i.test(lines[i])) {
        bedLines.push(lines.slice(Math.max(0, i-2), Math.min(lines.length, i+4)).join(" | "));
      }
    }
    return {
      plans: plans.filter(p => p.includes("Bed") && p.includes("$")),
      bedLines: bedLines.slice(0, 10),
      h1: document.querySelector("h1")?.textContent?.trim()
    };
  });
}

for (const v of verified) {
  if (v.tabId === 787784315) continue; // Kendall Crossing on Apartments.com is already verified
  console.log(`\nChecking tab ${v.tabId}: ${v.building}`);
  const fp = await getCleanFloorPlans(v.tabId);
