const cands = JSON.parse((await read("tmp://rent_candidates.json")).text);
let verified = JSON.parse((await read("tmp://verified_listings.json")).text);
const workerTabId = 787784308;

async function checkCommute(address) {
  const origin = encodeURIComponent(address);
  const dest = encodeURIComponent("Massachusetts Institute of Technology, 77 Massachusetts Ave, Cambridge, MA 02139");
  const url = `https://www.google.com/maps/dir/${origin}/${dest}/`;
  await tool.navigate({ tabId: workerTabId, url });
  await tool.wait_for({ tabId: workerTabId, condition: "dom_settled", timeout_ms: 6000 });

  const res = await browserjs(workerTabId, () => {
    const text = document.body.innerText;
    const matches = Array.from(text.matchAll(/(\d+\s*hr\s*)?(\d+)\s*min/gi)).map(m => m[0]);
    return matches.slice(0, 6);
  });
  return res;
}

// Process candidates 10 to 18
for (let i = 10; i <= 18 && verified.length < 20; i++) {
  const cand = cands[i];
  console.log(`\n[${i}] Checking: ${cand.name} (${cand.url})`);

  const newTab = await tool.tabs_create({ url: cand.url });
  const tabId = newTab.details.tabId;
  await new Promise(r => setTimeout(r, 1200));

  try {
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  } catch(e) {}

  const info = await browserjs(tabId, () => {
    const h1 = document.querySelector("h1")?.textContent?.trim();
    const addr = document.querySelector("[data-tid='property-address'], address, .property-address")?.textContent?.trim() || "";
    const text = document.body.innerText;

    // Find lines with Bed and price
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    const plans = [];
    for (let j = 0; j < lines.length; j++) {
      if (/1\s*Bed|2\s*Bed|Studio/i.test(lines[j])) {
        const slice = lines.slice(Math.max(0, j-2), Math.min(lines.length, j+5)).join(" | ");
        plans.push(slice);
      }
    }
    return { h1, addr, plans: plans.slice(0, 10), fullText: text.slice(0, 2000) };
  });

  console.log("H1:", info.h1);
  console.log("Plans sample:", info.plans.slice(0, 3));

  // Parse 1-bed and 2-bed prices
  let matched = null;

  // Let's parse all mentions of 1 Bed and 2 Bed with prices
  for (const plan of info.plans) {
    // Check 1 bed
    const m1 = plan.match(/1\s*Bed(?:room)?[\s\S]{0,30}\$([0-9,]+)/i) || plan.match(/\$([0-9,]+)[\s\S]{0,30}1\s*Bed(?:room)?/i);
    if (m1) {
      const price = parseInt(m1[1].replace(/,/g, ''), 10);
      if (price >= 1200 && price <= 3000) {
        matched = { beds: "1 Bed", rent: `$${price.toLocaleString()}` };
        break;
      }
    }
    // Check 2 bed
    const m2 = plan.match(/2\s*Bed(?:room)?(?:s)?[\s\S]{0,30}\$([0-9,]+)/i) || plan.match(/\$([0-9,]+)[\s\S]{0,30}2\s*Bed(?:room)?(?:s)?/i);
    if (m2) {
      const price = parseInt(m2[1].replace(/,/g, ''), 10);
      if (price >= 1500 && price <= 5000) {
        matched = { beds: "2 Bed", rent: `$${price.toLocaleString()}` };
        // Don't break immediately if we might find a 1-bed, but 2-bed under 5000 is valid!
      }
    }
  }

  // If not found from plans, check fullText
  if (!matched) {
    const text = info.fullText;
    const m1 = text.match(/1\s*Bed(?:room)?[\s\S]{0,50}\$([0-9,]+)/i) || text.match(/\$([0-9,]+)[\s\S]{0,50}1\s*Bed(?:room)?/i);
    if (m1) {
      const price = parseInt(m1[1].replace(/,/g, ''), 10);
      if (price >= 1200 && price <= 3000) {
        matched = { beds: "1 Bed", rent: `$${price.toLocaleString()}` };
      }
    }
    if (!matched) {
      const m2 = text.match(/2\s*Bed(?:room)?(?:s)?[\s\S]{0,50}\$([0-9,]+)/i) || text.match(/\$([0-9,]+)[\s\S]{0,50}2\s*Bed(?:room)?(?:s)?/i);
      if (m2) {
        const price = parseInt(m2[1].replace(/,/g, ''), 10);
        if (price >= 1500 && price <= 5000) {
          matched = { beds: "2 Bed", rent: `$${price.toLocaleString()}` };
        }
      }
    }
  }

  if (!matched) {
    console.log("No valid 1-bed <= 3000 or 2-bed <= 5000. Closing tab.");
    await tool.tabs_close({ tabId });
    continue;
  }

  console.log(`Matched: ${matched.beds}, ${matched.rent}`);
  const addressToCheck = cand.address || info.addr || (info.h1 + ", Cambridge, MA");
  const commute = await checkCommute(addressToCheck);
  console.log("Commute times:", commute);

  const minutes = commute.map(t => {
    const m = t.match(/(\d+)\s*min/);
    return m ? parseInt(m[1], 10) : 999;
  });
  const bestMin = Math.min(...minutes);

  if (bestMin <= 20) {
    console.log(`Commute OK (${bestMin} min). KEEPING TAB ${tabId} OPEN!`);
    verified.push({
      tabId,
      building: info.h1 || cand.name,
      address: cand.address || info.addr,
      rent: matched.rent,
      beds: matched.beds,
      commute: `${bestMin} min to MIT`,
      link: cand.url
    });
    await write("tmp://verified_listings.json", JSON.stringify(verified, null, 2));
  } else {
    console.log(`Commute > 20 min (${bestMin} min). Closing tab.`);
    await tool.tabs_close({ tabId });
  }
}

console.log(`Verified listings so far: ${verified.length}`);

