  let matched = null;
  if (data.summaryMatch) {
    for (const s of data.summaryMatch) {
      const priceM = s.match(/\$([0-9,]+)/);
      const price = priceM ? parseInt(priceM[1].replace(/,/g, ''), 10) : 0;
      if (/1\s*Bed/i.test(s) && price >= 1000 && price <= 3000) {
        matched = { beds: "1 Bed", rent: `$${price.toLocaleString()}` };
        break;
      }
      if (/2\s*Bed/i.test(s) && price >= 1500 && price <= 5000) {
        matched = { beds: "2 Bed", rent: `$${price.toLocaleString()}` };
      }
    }
  }

  // Fallback regex on sample text
  if (!matched) {
    const m1 = data.sample.match(/1\s*Bed[\s\S]{0,30}\$([0-9,]+)/i) || data.sample.match(/\$([0-9,]+)[\s\S]{0,30}1\s*Bed/i);
    if (m1) {
      const p = parseInt(m1[1].replace(/,/g, ''), 10);
      if (p >= 1000 && p <= 3000) matched = { beds: "1 Bed", rent: `$${p.toLocaleString()}` };
    }
    if (!matched) {
      const m2 = data.sample.match(/2\s*Bed[\s\S]{0,30}\$([0-9,]+)/i) || data.sample.match(/\$([0-9,]+)[\s\S]{0,30}2\s*Bed/i);
      if (m2) {
        const p = parseInt(m2[1].replace(/,/g, ''), 10);
        if (p >= 1500 && p <= 5000) matched = { beds: "2 Bed", rent: `$${p.toLocaleString()}` };
      }
    }
  }

  if (!matched) {
    console.log("No matching 1-bed <= 3000 or 2-bed <= 5000. Closing tab.");
    await tool.tabs_close({ tabId });
    continue;
  }

  console.log(`Candidate MATCHED: ${matched.beds}, ${matched.rent}`);
  const addressToCheck = cand.address || data.addr || (data.h1 + ", Cambridge, MA");
  const commute = await checkCommute(addressToCheck);
  console.log("Commute times:", commute);

  const minutes = commute.map(t => {
    const m = t.match(/(\d+)\s*min/);
    return m ? parseInt(m[1], 10) : 999;
  });
  const bestMin = Math.min(...minutes);

  if (bestMin <= 20) {
    console.log(`Commute OK (${bestMin} min). KEEPING TAB ${tabId} OPEN!`);
    verified.push({
      tabId,
      building: data.h1 || cand.name,
      address: cand.address || data.addr,
      rent: matched.rent,
      beds: matched.beds,
      commute: `${bestMin} min to MIT`,
      link: cand.url
    });
    await write("tmp://verified_listings.json", JSON.stringify(verified, null, 2));
  } else {
    console.log(`Commute > 20 min (${bestMin} min). Closing tab.`);
    await tool.tabs_close({ tabId });
  }
}

