const tabId = 787784372;
const verified = JSON.parse((await read("tmp://verified_listings.json")).text);

// Prepare TSV data
const header = ["Building or Address", "Monthly Rent", "Number of Bedrooms", "Estimated Commute Time to MIT", "Direct Listing Link"];
const rows = [header];

for (const v of verified) {
  const buildingOrAddr = `${v.building} (${v.address})`;
  rows.push([
    buildingOrAddr,
    v.rent,
    v.beds,
    v.commute,
    v.link
  ]);
}

const tsv = rows.map(r => r.join("\t")).join("\n");
await write("tmp://sheet_data.tsv", tsv);
console.log(`Generated TSV with ${rows.length} rows.`);

// Step 1: Click "Got it" button around [545, 412]
await tool.mouse({
  action: "left_click",
  tabId,
  coordinate: [545, 412]
});

await new Promise(r => setTimeout(r, 1000));

// Step 2: Click cell A1 around [80, 355]
await tool.mouse({
  action: "left_click",
  tabId,
  coordinate: [80, 355]
});

await new Promise(r => setTimeout(r, 1000));

// Step 3: Write to clipboard inside the page
await browserjs(tabId, async (tsvData) => {
  await navigator.clipboard.writeText(tsvData);
}, tsv);

// Step 4: Press ControlOrMeta+v
await tool.press({
  tabId,
  keys: "ControlOrMeta+v"
});

// Wait 2 seconds for paste to process
await new Promise(r => setTimeout(r, 2000));

// Take screenshot to verify
const shot = await browser.screenshot({ tabId });
console.log("Post-paste screenshot URI:", shot.image);

